/* China PBoC Gold Reserves Tracker: reads data/*.csv (generated by analyze.py) and draws the page.
   All text goes through i18n (dictionary in strings.js); volumes are formatted as tonnes / ounces and values as
   USD by the helpers below. The whole page redraws on a language switch. Each time-series chart has its own
   range picker; the headline figures and the phase table do not depend on them. */
(function () {
  const { num, fmtPct, signCls } = kit;
  const t = (k, v) => i18n.t(k, v);
  const isZh = () => i18n.lang === 'zh';
  const UPDATE_CMD = 'python -m investdiy.cn_track_pboc_gold';
  const STALE_WEEKDAYS = 32;   // SAFE publishes a month-end around the 7th of the next month: normally at most ~27 weekdays old
  const $ = (id) => document.getElementById(id);
  const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };
  const inRange = ([s, e]) => (r) => r.d >= s && r.d <= e;

  // ---- units: tonnes / 10,000 oz (data files) -> "吨 / 万盎司" or "t / m oz"; USD 100 millions -> "亿美元" or "USD bn" ----
  const f = (v, d) => d3.format(`,.${d}f`)(Math.abs(v));
  const sgn = (v, withSign) => (withSign && v > 0 ? '+' : v < 0 ? '−' : '');
  const fmtT = (v, { sign = false, digits = 1 } = {}) => `${sgn(v, sign)}${f(v, digits)}${isZh() ? ' 吨' : ' t'}`;
  const fmtOz = (v, { sign = false } = {}) => (isZh() ? `${sgn(v, sign)}${f(v, 0)} 万盎司` : `${sgn(v, sign)}${f(v / 100, 2)}m oz`);
  const fmtUsd = (v) => (isZh() ? `${f(v, 0)} 亿美元` : `$${f(v / 10, 1)}bn`);
  const fmtPrice = (v) => (isZh() ? `${f(v, 0)} 美元/盎司` : `$${f(v, 0)}/oz`);
  const axisUsd = (v) => (isZh() ? d3.format(',')(v) : d3.format(',~f')(v / 10));
  const monthDate = (m) => new Date(`${m}-01T00:00:00Z`);

  let D = null;          // loaded data
  const R = {};          // range pickers, one per chart

  // ---------------- header ----------------
  function drawHeader(k) {
    const set = (id, text, cls = '') => { const e = $(id); e.textContent = text; e.className = `kpi-value ${cls}`; };
    const chgT = num(k.chg_t), chgOz = num(k.chg_10k_oz), ytd = num(k.ytd_t), streak = num(k.streak);
    const prevMonth = d3.utcFormat('%Y-%m')(d3.utcMonth.offset(monthDate(k.month), -1));
    set('k-hold', fmtT(num(k.gold_t)));
    $('k-hold-sub').textContent = t('k.hold.sub', { oz: fmtOz(num(k.gold_10k_oz)), m: k.month });
    set('k-chg', fmtT(chgT, { sign: true }), signCls(chgT));
    $('k-chg-sub').textContent = t('k.chg.sub', { oz: fmtOz(chgOz, { sign: true }), m: prevMonth });
    set('k-streak', streak ? t('k.streak.value', { n: streak }) : '0', streak ? 'up' : '');
    $('k-streak-sub').textContent = streak ? t('k.streak.sub', { m: k.streak_start }) : t('k.streak.none');
    set('k-ytd', fmtT(ytd, { sign: true }), signCls(ytd));
    $('k-ytd-sub').textContent = k.yoy_t === '' ? '—' : t('k.ytd.sub', { t: fmtT(num(k.yoy_t), { sign: true }) });
    set('k-value', fmtUsd(num(k.gold_usd_yi)));
    $('k-value-sub').textContent = t('k.value.sub', { c: fmtPct(num(k.gold_usd_chg_pct)), s: `${num(k.gold_share_pct).toFixed(2)}%` });
    set('k-price', isZh() ? `${kit.fmtNum(num(k.price_usd_oz))} 美元` : `$${kit.fmtNum(num(k.price_usd_oz))}`);   // per ounce, in the label
    $('k-price-sub').textContent = t('k.price.sub', { c: fmtPct(num(k.price_chg_pct)) });
    $('asof').textContent = t('common.asof', { d: k.month });

    const lead = i18n.rich('take.now', { m: k.month, oz: fmtOz(num(k.gold_10k_oz)), t: fmtT(num(k.gold_t)) });
    const move = chgOz > 0 ? i18n.rich('take.up', { chg: fmtT(chgT), n: streak, start: k.streak_start })
      : chgOz < 0 ? i18n.rich('take.down', { chg: fmtT(Math.abs(chgT)) }) : [t('take.flat')];
    const rest = i18n.rich('take.ytd', { ytd: fmtT(ytd, { sign: true }), usd: fmtUsd(num(k.gold_usd_yi)), share: `${num(k.gold_share_pct).toFixed(2)}%` });
    $('take-now').replaceChildren(...lead, ...move, ...rest);
    $('take-src').textContent = k.source === 'safe' && k.released ? t('take.src', { d: k.released }) : t('take.srcImf');

    const res = num(k.check_mismatch) ? t('a.checkBad', { k: k.check_mismatch }) : t('a.checkOk');
    $('a-check').innerHTML = t('a.check', { from: k.check_from, to: k.check_to, n: k.check_months, result: res });
  }

  // ---------------- shared chart frame ----------------
  /** svg + x (time) / y (linear) axes; returns {svg, x, y, W, H, m} */
  function frame(box, rows, { H, yDomain, yFmt, xPad = 0 }) {
    kit.ready(box);
    const W = Math.max(280, box.clientWidth), m = { t: 10, r: 14, b: 26, l: 56 };
    const [d0, d1] = d3.extent(rows, (r) => r.d);
    const x = d3.scaleUtc([d0, xPad ? d3.utcMonth.offset(d1, xPad) : d1], [m.l, W - m.r]);
    const y = d3.scaleLinear(yDomain, [H - m.b, m.t]).nice();
    const svg = d3.select(box).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${H}`);
    const years = (d1 - d0) / 3.156e10, n = Math.max(3, Math.floor(W / 100));
    // longer ranges tick on whole years only, so a label never repeats
    const ticks = years > 3 ? d3.utcYear.every(Math.ceil(years / n)) : n;
    const ax = svg.append('g').attr('transform', `translate(0,${H - m.b})`)
      .call(d3.axisBottom(x).ticks(ticks).tickFormat(d3.utcFormat(years > 3 ? '%Y' : '%Y-%m')).tickSizeOuter(0));
    const ay = svg.append('g').attr('transform', `translate(${m.l},0)`)
      .call(d3.axisLeft(y).ticks(6).tickFormat(yFmt).tickSize(-(W - m.l - m.r)));
    ay.select('.domain').remove();
    kit.axisStyle(ax, ay);
    return { svg, x, y, W, H, m };
  }

  /** Hover layer: a rule following the nearest row, tooltip lines from tipLines(row) */
  function hover({ svg, x, m, W, H }, card, rows, tipLines, dotY, color) {
    const tt = kit.tip(card);
    const rule = svg.append('line').attr('y1', m.t).attr('y2', H - m.b).style('stroke', 'var(--axis)').style('opacity', 0);
    const dot = dotY ? svg.append('circle').attr('r', 4).style('fill', color).style('stroke', 'var(--panel)').style('stroke-width', 2).style('opacity', 0) : null;
    const bis = d3.bisector((r) => r.d).center;
    svg.append('rect').attr('x', m.l).attr('y', m.t).attr('width', W - m.l - m.r).attr('height', H - m.t - m.b)
      .style('fill', 'transparent')
      .on('mousemove', (event) => {
        const r = rows[bis(rows, x.invert(d3.pointer(event)[0]))];
        rule.attr('x1', x(r.d)).attr('x2', x(r.d)).style('opacity', 1);
        if (dot) dot.attr('cx', x(r.d)).attr('cy', dotY(r)).style('opacity', 1);
        tt.show(event, tipLines(r));
      })
      .on('mouseleave', () => { tt.hide(); rule.style('opacity', 0); if (dot) dot.style('opacity', 0); });
  }

  const legendItem = (color, text, line) => {
    const s = el('span'); const i = el('i', line ? 'line' : null);
    i.style.background = color; if (!line) i.style.opacity = '0.3';
    s.append(i, text); return s;
  };

  const monthTip = (r) => [
    { text: r.month },
    { text: t('tip.hold', { t: fmtT(r.tn), oz: fmtOz(r.oz) }), color: 'var(--s2)' },
    { text: t('tip.chg', { t: fmtT(r.chgT, { sign: true }), oz: fmtOz(r.chgOz, { sign: true }) }) },
    { text: t(`tip.src.${r.source}`) },
  ];

  // ---------------- holdings (tonnes, step line) ----------------
  function drawHoldings() {
    const box = $('hold-box'), card = $('holdings');
    const rng = R.hold.get();
    const rows = D.monthly.filter(inRange(rng));
    if (rows.length < 2) { kit.fail(box); return; }
    const up = kit.color('--up');
    const fr = frame(box, rows, { H: 320, yDomain: [0, d3.max(rows, (r) => r.tn)], yFmt: d3.format(','), xPad: 0 });
    const { svg, x, y, m, H, W } = fr;
    const clampX = (d) => Math.max(m.l, Math.min(W - m.r, x(d)));
    svg.append('g').selectAll('rect').data(D.phases.filter((p) => p.kind === 'buying' && p.e >= rng[0] && p.s <= rng[1])).join('rect')
      .attr('x', (p) => clampX(p.s)).attr('width', (p) => Math.max(2, clampX(p.e) - clampX(p.s)))
      .attr('y', m.t).attr('height', H - m.b - m.t).style('fill', up).style('opacity', 0.1);
    const area = d3.area((r) => x(r.d), y(0), (r) => y(r.tn)).curve(d3.curveStepAfter);
    const line = d3.line((r) => x(r.d), (r) => y(r.tn)).curve(d3.curveStepAfter);
    svg.append('path').datum(rows).attr('d', area).style('fill', 'var(--s2)').style('opacity', 0.12);
    svg.append('path').datum(rows).attr('d', line).style('fill', 'none').style('stroke', 'var(--s2)').style('stroke-width', 2).style('stroke-linejoin', 'round');
    hover(fr, card, rows, monthTip, (r) => y(r.tn), 'var(--s2)');
    $('hold-legend').replaceChildren(legendItem('var(--s2)', t('hold.lgLine'), true), legendItem(up, t('hold.lgBand')));
  }

  // ---------------- monthly changes (bars, tonnes) ----------------
  function drawChanges() {
    const box = $('chg-box'), card = $('changes');
    const rows = D.monthly.filter(inRange(R.chg.get()));
    if (rows.length < 2) { kit.fail(box); return; }
    const ext = d3.extent([0, ...rows.map((r) => r.chgT)]);
    const fr = frame(box, rows, { H: 240, yDomain: ext, yFmt: d3.format(','), xPad: 1 });
    const { svg, x, y } = fr;
    const bw = Math.max(1, (x(d3.utcMonth.offset(rows[0].d, 1)) - x(rows[0].d)) - 1);
    svg.append('g').selectAll('rect').data(rows.filter((r) => r.chgOz !== 0)).join('rect')
      .attr('x', (r) => x(r.d)).attr('width', bw)
      .attr('y', (r) => y(Math.max(0, r.chgT))).attr('height', (r) => Math.max(1, Math.abs(y(r.chgT) - y(0))))
      .style('fill', (r) => (r.chgT > 0 ? 'var(--up)' : 'var(--down)'));
    svg.append('line').attr('x1', fr.m.l).attr('x2', fr.W - fr.m.r).attr('y1', y(0)).attr('y2', y(0)).style('stroke', 'var(--axis)');
    // bars start at the month: shift the hover rows to the bar centres
    const mid = rows.map((r) => ({ ...r, d: x.invert(x(r.d) + bw / 2) }));
    hover(fr, card, mid, monthTip);
  }

  // ---------------- by year (bars, tonnes) ----------------
  function drawAnnual() {
    const box = $('year-box'), card = $('annual');
    const [s, e] = R.year.get();
    const rows = D.annual.filter((r) => r.d >= d3.utcYear.floor(s) && r.d <= e);
    if (!rows.length) { kit.fail(box); return; }
    kit.ready(box);
    const W = Math.max(280, box.clientWidth), H = 240, m = { t: 10, r: 14, b: 26, l: 56 };
    const x = d3.scaleBand(rows.map((r) => r.year), [m.l, W - m.r]).paddingInner(rows.length > 30 ? 0.15 : 0.3);
    const y = d3.scaleLinear(d3.extent([0, ...rows.map((r) => r.chgT)]), [H - m.b, m.t]).nice();
    const svg = d3.select(box).append('svg').attr('width', '100%').attr('viewBox', `0 0 ${W} ${H}`);
    const every = Math.max(1, Math.ceil(rows.length / Math.floor((W - m.l - m.r) / 44)));
    const ax = svg.append('g').attr('transform', `translate(0,${H - m.b})`)
      .call(d3.axisBottom(x).tickValues(rows.map((r) => r.year).filter((_, i) => (rows.length - 1 - i) % every === 0)).tickSizeOuter(0));
    const ay = svg.append('g').attr('transform', `translate(${m.l},0)`).call(d3.axisLeft(y).ticks(6).tickFormat(d3.format(',')).tickSize(-(W - m.l - m.r)));
    ay.select('.domain').remove();
    kit.axisStyle(ax, ay);
    const tt = kit.tip(card);
    const g = svg.append('g').selectAll('g').data(rows).join('g');
    g.append('rect')
      .attr('x', (r) => x(r.year)).attr('width', x.bandwidth())
      .attr('y', (r) => y(Math.max(0, r.chgT))).attr('height', (r) => (r.chgOz ? Math.max(1, Math.abs(y(r.chgT) - y(0))) : 0))
      .attr('rx', Math.min(2, x.bandwidth() / 4))
      .style('fill', (r) => (r.chgT >= 0 ? 'var(--up)' : 'var(--down)')).style('opacity', (r) => (r.partial ? 0.5 : 1));
    // hit targets cover the whole column, not just the bar
    g.append('rect').attr('x', (r) => x(r.year) - (x.step() - x.bandwidth()) / 2).attr('width', x.step())
      .attr('y', m.t).attr('height', H - m.t - m.b).style('fill', 'transparent')
      .on('mousemove', (event, r) => tt.show(event, [
        { text: t('tip.year', { y: r.year, partial: r.partial ? t('tip.partial', { m: r.lastMonth }) : '' }) },
        { text: t('tip.yearChg', { t: fmtT(r.chgT, { sign: true }) }), color: r.chgT >= 0 ? 'var(--up)' : 'var(--down)' },
        { text: t('tip.yearMonths', { n: r.addMonths }) },
        { text: t('tip.yearEnd', { t: fmtT(r.endT) }) },
      ]))
      .on('mouseleave', () => tt.hide());
    svg.append('line').attr('x1', m.l).attr('x2', W - m.r).attr('y1', y(0)).attr('y2', y(0)).style('stroke', 'var(--axis)');
  }

  // ---------------- value and share (market valuation, from 2015-06) ----------------
  function drawLine(boxId, picker, value, yFmt, color, tipLines) {
    const box = $(boxId), card = $('value');
    const rows = D.market.filter(inRange(picker.get()));
    if (rows.length < 2) { kit.fail(box); return; }
    const fr = frame(box, rows, { H: 260, yDomain: [0, d3.max(rows, value)], yFmt });
    const { svg, x, y } = fr;
    svg.append('path').datum(rows).attr('d', d3.area((r) => x(r.d), y(0), (r) => y(value(r)))).style('fill', color).style('opacity', 0.1);
    svg.append('path').datum(rows).attr('d', d3.line((r) => x(r.d), (r) => y(value(r))))
      .style('fill', 'none').style('stroke', color).style('stroke-width', 2).style('stroke-linejoin', 'round');
    hover(fr, card, rows, tipLines, (r) => y(value(r)), color);
  }
  const valueTip = (r) => [
    { text: r.month },
    { text: t('tip.usd', { v: fmtUsd(r.usd) }), color: 'var(--s2)' },
    { text: t('tip.price', { p: fmtPrice(r.price) }) },
    { text: t('tip.hold', { t: fmtT(r.tn), oz: fmtOz(r.oz) }) },
  ];
  const shareTip = (r) => [
    { text: r.month },
    { text: t('tip.share', { s: `${r.share.toFixed(2)}%` }), color: 'var(--s1)' },
    { text: t('tip.usd', { v: fmtUsd(r.usd) }) },
    { text: t('tip.total', { v: fmtUsd(r.total) }) },
  ];
  const drawUsd = () => drawLine('usd-box', R.usd, (r) => r.usd, axisUsd, 'var(--s2)', valueTip);
  const drawShare = () => drawLine('share-box', R.share, (r) => r.share, (v) => `${v}%`, 'var(--s1)', shareTip);

  // ---------------- phases table ----------------
  function drawPhases() {
    const tb = document.querySelector('#ph-table tbody');
    tb.replaceChildren(...D.phaseRows.map((p) => {
      const tr = el('tr');
      const td = (text, cls) => { const c = el('td', cls, text); tr.appendChild(c); return c; };
      const kind = td(t(`v.${p.kind}`));
      if (p.ongoing === '1') kind.appendChild(el('span', 'pill', t('ph.ongoing')));
      td(p.start); td(p.end); td(p.months); td(p.add_months);
      const a = num(p.added_t);
      td(fmtNumSigned(a, 1), signCls(a));
      td(isZh() ? fmtNumSigned(num(p.added_10k_oz), 0) : fmtNumSigned(num(p.added_10k_oz) / 100, 2), signCls(a));
      td(kit.fmtNum(num(p.end_t), 1));
      td(p.cost_usd_yi === '' ? '—' : (isZh() ? kit.fmtNum(num(p.cost_usd_yi), 0) : kit.fmtNum(num(p.cost_usd_yi) / 10, 1)));
      td(p.avg_price_usd_oz === '' ? '—' : kit.fmtNum(num(p.avg_price_usd_oz), 0));
      return tr;
    }));
  }
  const fmtNumSigned = (v, d) => `${v > 0 ? '+' : v < 0 ? '−' : ''}${f(v, d)}`;

  // ---------------- loading ----------------
  const FILES = ['kpi', 'monthly', 'annual', 'phases'];
  const BOXES = ['hold-box', 'chg-box', 'year-box', 'usd-box', 'share-box'];

  function drawAll() {
    if (!D) return;
    drawHeader(D.kpi);
    drawHoldings();
    drawChanges();
    drawAnnual();
    drawUsd();
    drawShare();
    drawPhases();
  }

  $('take-now').textContent = t('common.loading');
  kit.sectionNav($('secnav'));
  kit.downloadLinks('data/');

  Promise.all(FILES.map((x) => kit.csv(`data/${x}.csv`))).then(([kpi, monthly, annual, phases]) => {
    const rows = monthly.map((r) => ({
      month: r.month, d: monthDate(r.month), source: r.source, market: r.valuation === 'market',
      oz: num(r.gold_10k_oz), tn: num(r.gold_t), chgOz: num(r.chg_10k_oz), chgT: num(r.chg_t),
      usd: num(r.gold_usd_yi), total: num(r.total_usd_yi), share: num(r.gold_share_pct), price: num(r.price_usd_oz),
    }));
    D = {
      kpi: kpi[0],
      monthly: rows,
      market: rows.filter((r) => r.market),
      annual: annual.map((r) => ({
        year: r.year, d: new Date(`${r.year}-01-01T00:00:00Z`), chgOz: num(r.chg_10k_oz), chgT: num(r.chg_t),
        addMonths: r.add_months, endT: num(r.end_t), partial: r.partial === '1',
        lastMonth: kpi[0].month,
      })),
      phaseRows: phases,
      // bands run from the start of the first month to the end of the last one
      phases: phases.map((p) => ({ kind: p.kind, s: monthDate(p.start), e: d3.utcMonth.offset(monthDate(p.end), 1) })),
    };
    const [dMin, dMax] = d3.extent(rows, (r) => r.d);
    const [vMin, vMax] = d3.extent(D.market, (r) => r.d);
    R.hold = kit.rangePicker($('hold-range'), { min: dMin, max: dMax, initial: 'all', onChange: drawHoldings });
    R.chg = kit.rangePicker($('chg-range'), { min: dMin, max: dMax, initial: '5y', onChange: drawChanges });
    R.year = kit.rangePicker($('year-range'), { min: dMin, max: dMax, initial: 'all', onChange: drawAnnual });
    R.usd = kit.rangePicker($('usd-range'), { min: vMin, max: vMax, initial: 'all', onChange: drawUsd });
    R.share = kit.rangePicker($('share-range'), { min: vMin, max: vMax, initial: 'all', onChange: drawShare });
    kit.markStale($('stale'), D.kpi.as_of, STALE_WEEKDAYS);
    drawAll();
    kit.onRedraw(drawAll);
  }).catch((err) => {
    console.error(err);
    const show = () => { $('take-now').textContent = t('loadError', { cmd: UPDATE_CMD }); };
    show();
    i18n.onChange(show);
    BOXES.forEach((id) => kit.fail($(id)));
  });
})();
